# The insertion and recovery grasp failed, leaving too few actions for another complete manipulation attempt.
# Return both arms toward their saved starting joints and stop on convergence or the official episode end.
for i in range(24):
    obs, reward, terminated, truncated, info = step(origin)
    if terminated or truncated:
        break
    error = sum((obs['state'][arm + '_arm_joint_state'][j] - origin[arm + '_arm_joint_state'][j])**2
                for arm in ['left', 'right'] for j in range(6))
    if i >= 11 and error < 0.0004:
        break
print({'reward': reward, 'terminated': terminated, 'truncated': truncated, 'info': info})

